∀ {R : Type u} {S : Type v} [inst : CommRing R] [inst_1 : IsDomain R] [inst_2 : Semiring S] {p : Polynomial S}
  {f : S →+* R},
  Function.Injective ⇑f → ∀ {x : R}, p ≠ 0 → (x ∈ (Polynomial.map f p).roots ↔ Polynomial.eval₂ f x p = 0)

∀ {S : Type v} {T : Type w} [inst : CommRing T] [IsDomain T] [inst_2 : CommRing S] [inst_3 : IsDomain S]
  [inst_4 : Algebra T S] [Module.IsTorsionFree T S] {a : T},
  a ≠ 0 → ∀ (n : ℕ), (Polynomial.C a * Polynomial.X ^ n).aroots S = n • {0}

∀ {S : Type v} {T : Type w} [inst : CommRing T] [IsDomain T] [inst_2 : CommRing S] [inst_3 : IsDomain S]
  [inst_4 : Algebra T S] [Module.IsTorsionFree T S] {a : T},
  a ≠ 0 → ∀ (n : ℕ), ((Polynomial.monomial n) a).aroots S = n • {0}

∀ {R : Type u} {S : Type v} [inst : CommRing R] [inst_1 : IsDomain R] [inst_2 : CommRing S] {p : Polynomial S}
  [inst_3 : Algebra S R],
  Function.Injective ⇑(algebraMap S R) → ∀ {x : R}, p ≠ 0 → (x ∈ p.rootSet R ↔ (Polynomial.aeval x) p = 0)

∀ {R : Type u} {S : Type v} [inst : CommRing R] [inst_1 : IsDomain R] [inst_2 : CommRing S] [inst_3 : Algebra S R]
  {G : Type u_1} [inst_4 : Group G] [inst_5 : MulSemiringAction G R] [SMulCommClass G S R] {f : Polynomial S} {g : G}
  {x : R}, g • x ∈ f.rootSet R ↔ x ∈ f.rootSet R

∀ {R : Type u} {S : Type v} [inst : CommRing R] [inst_1 : IsDomain R] [inst_2 : CommRing S] [inst_3 : Algebra S R]
  {G : Type u_1} [inst_4 : Monoid G] [inst_5 : MulSemiringAction G R] [inst_6 : SMulCommClass G S R] {f : Polynomial S}
  (g : G) (x : ↑(f.rootSet R)), ↑(g • x) = g • ↑x
